-- Guia "Fátima em 3 dias: quando ir, dias de maior movimento e o museu a € 3 (cerca de R$ 20)" (rascunho). Gerado por tools/gerar-migration-guia.ts a partir de content/guias/fatima-em-3-dias.json.
-- Entra como rascunho: publique pelo painel (/admin-blog.html) depois de conferir a pré-visualização.
INSERT INTO blog_posts (id, slug, status, region_id, title, title_highlight, summary, lede, destination, cta_title, cover_url, cover_url_small, cover_alt, featured, body, reading_minutes)
VALUES ('e5f8cf6f-224c-4312-909e-9a86b970bacc', 'fatima-em-3-dias', 'draft', 'portugal', 'Fátima em 3 dias: quando ir, dias de maior movimento e o museu a € 3 (cerca de R$ 20)', 'dias de maior movimento', 'Roteiro de Fátima em 3 dias só com logística: Santuário, Via-sacra, Aljustrel, bate-volta ao Mosteiro da Batalha, quando ir, dias de maior movimento, valores em euros e em reais e o guia em PDF de graça.', 'Os dias de maior movimento em Fátima são 12 e 13, de maio a outubro, e visitas curtas não exigem marcação. O roteiro, os horários e o guia completo vão no celular.', 'Fátima', NULL, '/assets/blog/fatima-3-dias.jpg', '/assets/blog/fatima-3-dias-m.jpg', 'Basílica de Nossa Senhora do Rosário, em Fátima, Portugal', 0, '[{"t":"pdf","href":"/guias/fatima-em-3-dias.pdf","note":"PDF de 16 páginas, feito para ler no celular. Grátis, sem cadastro."},{"t":"p","text":"Santuário, Via-sacra, Valinhos, Loca do Cabeço, Aljustrel e bate-volta ao Mosteiro da Batalha ou de Alcobaça, com horários, preços em euro e em reais e checklist. Este guia traz só logística."},{"t":"tip","items":["Visitas curtas e celebrações não exigem marcação. Os dias de maior movimento são 12 e 13, de maio a outubro.","Veja a seção Documentos e antes de ir.","Estimativas de tempo e esforço e dicas da Rota Certa são recomendações nossas, não dados oficiais. O real é aproximado, pela cotação de 19/11/2026."],"title":"Como usar este roteiro"},{"t":"whatsapp"},{"t":"afiliado"},{"t":"h","text":"O Santuário","label":"Dia 1"},{"t":"p","text":"Conhecer o conjunto do Santuário, na Cova da Iria, com calma: Recinto de Oração, basílicas e Capelinha das Aparições."},{"t":"img","src":"/assets/blog/fatima-esplanada.jpg","alt":"Santuário de Fátima, em Portugal","caption":"Santuário de Fátima.","credit":"Foto: Regan Dsouza / Pexels","w":1000,"h":667},{"t":"ul","items":["**Chegada, sugestão 8h30:** Chegue cedo e use os parques identificados do Santuário. Veja a seção Transporte e estacionamento.","**Manhã, sugestão 9h00 e 10h30:** Recinto de Oração e Basílica da Santíssima Trindade. Depois, a Basílica de Nossa Senhora do Rosário, o templo principal. Caminhada leve, cerca de 1 hora.","**12h00 e 12h30, Capelinha das Aparições:** Rosário às 12h00 e missa às 12h30 (agenda de quinta, 19/11/2026). Confira a agenda do dia em [fatima.pt/pt/schedule](https://www.fatima.pt/pt/schedule).","**Sugestão 13h00 e 15h00:** Almoço (seção Onde comer). Depois, a Capela do Santíssimo Sacramento: 200 lugares, acessível durante a totalidade do dia.","**Fim do dia:** 18h30, rosário na Capelinha, de segunda a sexta. 21h30, rosário e procissão das velas no Recinto de Oração (agenda de quinta, 19/11/2026). Fim de semana: confirme a agenda."]},{"t":"tip","items":["Os horários marcados como sugestão são da Rota Certa, para um dia de semana no horário de inverno, não dados oficiais."],"title":"Horários sugeridos"},{"t":"tip","items":["Principal: Recinto de Oração e basílicas","Grátis: Entrada no Recinto e nas basílicas, sem bilhete listado nas fontes","Opcional: Capela do Santíssimo Sacramento","**Nas atrações:** caminhada leve de cerca de 1 hora entre o Recinto e as basílicas, mais as celebrações que você escolher","**A pé:** caminhada leve dentro do conjunto do Santuário","**Esforço:** leve","Estimativas da Rota Certa, não dados oficiais. Não contam filas nem refeições.","**Dica da Rota Certa:** chegue cedo e use os parques identificados do Santuário."],"title":"Para planejar o Dia 1"},{"t":"p","text":"[Abrir a rota do Dia 1 no Google Maps](https://www.google.com/maps/search/?api=1&query=Santu%C3%A1rio%20de%20F%C3%A1tima)"},{"t":"passeio","busca":"Fátima Santuário passeio","title":"Passeios em Fátima"},{"t":"h","text":"Via-sacra e Aljustrel","label":"Dia 2"},{"t":"p","text":"Via-sacra, Valinhos, Loca do Cabeço e Aljustrel, com o Museu do Santuário à tarde."},{"t":"img","src":"/assets/blog/fatima-casa-de-pedra.jpg","alt":"Casa antiga de pedra com telhado de telha, em Fátima","caption":"Casa de pedra em Fátima.","credit":"Foto: Regan Dsouza / Pexels","w":1000,"h":667},{"t":"ul","items":["**Sugestão 9h00, Via-sacra:** Saída da Rotunda de Santa Teresa de Ourém (Rotunda Sul) rumo a Valinhos. A Via-sacra tem 14 estações, até o Calvário Húngaro. Caminhada de cerca de 40 minutos.","**Sugestão 9h45 e 10h30, Valinhos e Loca do Cabeço:** Valinhos, local de memória com monumento, fica entre a 8.ª e a 9.ª estações da Via-sacra. A Loca do Cabeço, também local de memória, fica a cerca de 2 km de Fátima.","**Sugestão 11h15, Aljustrel:** Poço do Arneiro. Casa de São Francisco e Santa Jacinta Marto: segunda a domingo, 9h00 às 12h45 e 14h00 às 17h45 (última entrada). Preço não informado. Chegue antes das 12h45. Casa da Irmã Lúcia: confirme horário e preço no [site do Santuário](https://www.fatima.pt/pt/pages/contactos).","**Sugestão 14h30, Museu do Santuário de Fátima:** Exposição permanente. Bilhete € 3 (cerca de R$ 20). Segunda a domingo, 9h00 às 12h15 e 14h00 às 17h15 (última entrada). Visita de cerca de 1 hora."]},{"t":"tip","items":["O Santuário publica a ordem do percurso de Aljustrel e Valinhos: Monumento dos Valinhos, Loca do Cabeço, Poço do Arneiro, Casa da Irmã Lúcia e Casa de São Francisco e Santa Jacinta Marto."],"title":"Ordem do percurso"},{"t":"tip","items":["Principal: Valinhos, Loca do Cabeço e Aljustrel","Grátis: Via-sacra e caminhada até Valinhos, sem bilhete listado nas fontes","Opcional: Museu do Santuário, € 3 (cerca de R$ 20)","**Nas atrações:** cerca de 4 a 5 horas, com paradas","**A pé:** Via-sacra de cerca de 40 minutos; Aljustrel e a Loca do Cabeço ficam a cerca de 2 km de Fátima","**Esforço:** moderado, com calçado confortável","Estimativas da Rota Certa, não dados oficiais.","**Dica da Rota Certa:** chegue à Casa de São Francisco e Santa Jacinta Marto antes das 12h45 e deixe o Museu para a tarde."],"title":"Para planejar o Dia 2"},{"t":"p","text":"[Abrir a rota do Dia 2 no Google Maps](https://www.google.com/maps/dir/?api=1&origin=Rotunda%20de%20Santa%20Teresa%20de%20Our%C3%A9m%2C%20F%C3%A1tima&waypoints=Valinhos%2C%20F%C3%A1tima%7CLoca%20do%20Cabe%C3%A7o%2C%20F%C3%A1tima&destination=Aljustrel%2C%20F%C3%A1tima&travelmode=walking)"},{"t":"passeio","busca":"Fátima Aljustrel Valinhos passeio","title":"Passeios em Aljustrel e Valinhos"},{"t":"h","text":"Mosteiro da Batalha","label":"Dia 3"},{"t":"p","text":"Bate-volta ao Mosteiro da Batalha, com Alcobaça como alternativa. Escolha um dos dois."},{"t":"img","src":"/assets/blog/fatima-batalha.jpg","alt":"Arcos góticos do Mosteiro da Batalha, em Portugal","caption":"Arcos góticos do Mosteiro da Batalha.","credit":"Foto: Efrem  Efre / Pexels","w":1000,"h":667},{"t":"ul","items":["**Manhã, saída de Fátima:** Vá de carro ou de táxi, para chegar perto da abertura. Sem fonte oficial de ônibus ou trem para este trecho.","**Manhã, Mosteiro da Batalha:** Adulto € 15 (cerca de R$ 98). 65 anos ou mais e 13 a 24 anos: € 7,50 (cerca de R$ 49). Até 12 anos grátis. Visita de cerca de 1h30 a 2 horas.","**Horário da Batalha:** de 16/10 a 31/3, 9h00 às 18h00 (última entrada 17h30). De 1/4 a 15/10, 9h00 às 18h30 (última entrada 18h00). Fechado em 1/1, Domingo de Páscoa, 1/5 e 25/12.","**Se preferir, Mosteiro de Alcobaça:** De 1/11 a 31/3, 9h00 às 17h30 (última entrada 17h00). Bilhete normal € 15 (cerca de R$ 98); 50% de desconto para 65+, 13 a 24 anos e famílias. Fecha em 1/1, Páscoa, 1/5, 20/8 e 25/12.","**Almoço e tarde:** Almoço na região (seção Onde comer). Volte a Fátima e faça a última caminhada no Recinto de Oração. Rosário às 18h30 na Capelinha, de segunda a sexta."]},{"t":"tip","items":["O site oficial do Mosteiro da Batalha avisa de mudanças no percurso de visita. Confira antes de ir.","Este guia não traz distância oficial entre Fátima e os mosteiros: confira o trajeto no mapa."],"title":"Percurso de visita e trajeto"},{"t":"tip","items":["Principal: Mosteiro da Batalha","Grátis: Última caminhada no Recinto de Oração, na volta a Fátima, sem bilhete listado nas fontes","Opcional: Mosteiro de Alcobaça, em vez da Batalha","**Nas atrações:** visita de cerca de 1h30 a 2 horas no mosteiro, mais a ida e a volta de carro ou de táxi","**A pé:** caminhada dentro do mosteiro e, de volta a Fátima, no Recinto de Oração","**Esforço:** leve","Estimativas da Rota Certa, não dados oficiais.","**Dica da Rota Certa:** escolha um só mosteiro e vá de carro ou de táxi, para chegar perto da abertura."],"title":"Para planejar o Dia 3"},{"t":"p","text":"[Abrir a rota do Dia 3 no Google Maps](https://www.google.com/maps/dir/?api=1&origin=Santu%C3%A1rio%20de%20F%C3%A1tima&destination=Mosteiro%20da%20Batalha&travelmode=driving)"},{"t":"passeio","busca":"Mosteiro da Batalha passeio saindo de Fátima","title":"Passeios ao Mosteiro da Batalha"},{"t":"h","text":"Santuário de Fátima: dados e agenda","label":"Atração principal"},{"t":"p","text":"O conjunto do Santuário fica na Cova da Iria e tem Recinto de Oração, basílicas e capelas."},{"t":"ul","items":["**Recinto:** 86 400 m², comporta cerca de 300 000 pessoas.","**Basílica da Santíssima Trindade:** 8633 lugares.","**Endereço e telefone:** Rua de Santa Isabel, 360, 2495-424 Fátima. +351 249 539 600.","**Agenda do dia:** Confira em [fatima.pt/pt/schedule](https://www.fatima.pt/pt/schedule) antes de ir."]},{"t":"tip","items":["O Santuário pede respeito, silêncio e limpeza nos espaços de oração."],"title":"Respeito e silêncio"},{"t":"h","text":"Dias de maior movimento e horário de inverno","label":"Quando ir"},{"t":"p","text":"Datas de maior movimento: dias 12 e 13, de maio a outubro."},{"t":"ul","items":["**Dias 12 e 13:** São as peregrinações aniversárias, de maio a outubro, segundo o Turismo Centro de Portugal. Em outubro de 2026, o Santuário contou cerca de 130 mil peregrinos na primeira noite. Se prefere menos gente, evite esses dias (recomendação da Rota Certa).","**Horário de inverno:** De 1/11 até a Páscoa. A missa das 11h00 é na Basílica de Nossa Senhora do Rosário (segunda a sexta) e na Basílica da Santíssima Trindade (fim de semana). Natal, Quaresma e Semana Santa terão alterações.","**Reserva:** Visitas curtas e celebrações não exigem marcação: \"não precisa de marcar lugar\", diz o Turismo Centro de Portugal. Grupos se registram no Departamento de Acolhimento e Pastoral, com antecedência."]},{"t":"tip","items":["O Santuário, citando a GNR, recomenda chegada antecipada, estacionamento nos parques identificados e saída gradual (notícia de 2025)."],"title":"Para os dias de maior movimento"},{"t":"h","text":"Transporte e estacionamento","label":"Na prática"},{"t":"p","text":"Veja como chegar de carro, de ônibus ou de trem."},{"t":"ul","items":["**Distâncias:** Lisboa 120 km, Porto 180 km, Leiria 25 km e Ourém 11 km. A A1 é a principal porta de entrada.","**Ônibus:** Operadores privados, como a FlixBus, ligam Lisboa e Porto ao Terminal Rodoviário de Fátima. Horários e preços mudam: consulte [FlixBus Lisboa](https://www.flixbus.com/bus-routes/bus-lisbon-fatima), [FlixBus Porto](https://www.flixbus.com/bus-routes/bus-porto-fatima) e [Rede Expressos](https://rede-expressos.pt/pt/).","**Trem e táxi:** Não confirmamos horários de trem nem a ligação até o Santuário: consulte a [CP](https://cp.pt/info/documents/d/cp/comboios-alfa-pendular-intercidades-lisboa-norte-sul-1). Táxi e transfer: sem fonte oficial de preço.","**De carro:** Em dias de peregrinação, use os parques identificados e chegue cedo. A [GNR](https://www.gnr.pt/fatima_carro.aspx) tem orientações publicadas (sem data)."]},{"t":"tip","items":["Confirme as condições de estacionamento no [site do Santuário](https://www.fatima.pt/pt/pages/contactos) e na [Câmara de Ourém](https://www.ourem.pt/)."],"title":"Estacionamento: confirme"},{"t":"h","text":"Onde comer","label":"Sabores"},{"t":"p","text":"Sem fonte oficial de preço, este guia não traz preço de refeição nem nome de restaurante."},{"t":"ul","items":["**Refeitório do Centro Pastoral:** O Centro Pastoral de Paulo VI, no lado poente do Santuário, tem refeitório self-service. Horário e preço não informados no site oficial.","**Hospedagem do Santuário:** Restaurante e bar constam entre as comodidades das unidades de hospedagem do Santuário.","**Pratos da região:** Em notícia de 2021, a Câmara Municipal de Ourém cita sopas de verde, carneiro guisado, coelho à moda da Ortiga, mexudas, chícharos com broa, feijão com abóbora, merendeiras salgadas e enchidos. O Turismo Centro de Portugal cita pratos de caça, como perdiz e coelho bravo, para Fátima."]},{"t":"tip","items":["**Dica da Rota Certa:** nos fins de semana de peregrinação, reserve a refeição com antecedência."]},{"t":"h","text":"Documentos e antes de ir","label":"Checklist"},{"t":"tip","items":["Segundo o Your Europe, o passaporte deve ter sido emitido nos últimos 10 anos e valer pelo menos 3 meses depois da data prevista de saída da UE. Estadas curtas: até 90 dias em qualquer período de 180."],"title":"Passaporte"},{"t":"ul","items":["**Visto, EES, ETIAS e meios financeiros:** Confira as regras de entrada vigentes nos sites oficiais: [Your Europe](https://europa.eu/youreurope/citizens/travel/entry-exit/non-eu-nationals/index_en.htm), [EUR-Lex](https://eur-lex.europa.eu/legal-content/PT/TXT/HTML/?uri=CELEX:32018R1806), [EES e ETIAS](https://home-affairs.ec.europa.eu/news/main-differences-between-ees-and-etias-what-travellers-need-know-2026-04-28_en) e [site do ETIAS](https://home-affairs.ec.europa.eu/policies/schengen/smart-borders/european-travel-information-authorisation-system_en). Veja antes de comprar a passagem.","**Seguro e roupa:** Seguro-viagem com cobertura médica é recomendação da Rota Certa. Sobre roupa, confira as orientações no site do Santuário."]},{"t":"tip","items":["Passaporte válido por 3 meses depois da saída.","Seguro-viagem com cobertura médica.","Agenda do dia do Santuário, em fatima.pt/pt/schedule.","Horários e preços dos mosteiros, nos sites oficiais.","Calçado confortável."],"title":"Checklist"},{"t":"h","text":"Orçamento","label":"Planejamento"},{"t":"p","text":"Por adulto, só itens com preço oficial."},{"t":"ul","items":["**Estacionamento nos parques do Santuário:** confirme, sem estimativa.","**Entrada no Recinto e nas basílicas:** sem bilhete listado.","**Museu do Santuário:** € 3 (cerca de R$ 20).","**Mosteiro da Batalha, adulto:** € 15 (cerca de R$ 98). Para 65+ e 13 a 24 anos: € 7,50 (cerca de R$ 49).","**Mosteiro de Alcobaça (alternativa):** € 15 (cerca de R$ 98).","**Casa de São Francisco e Santa Jacinta Marto:** preço não informado.","**Museu + Batalha (ou Alcobaça):** € 18 (cerca de R$ 117)."]},{"t":"p","text":"Total: € 18 (cerca de R$ 117), somando o Museu e a Batalha. Reais pela cotação de venda do Banco Central de 19/11/2026 (euro a R$ 6,4672), arredondados para cima. Fora da conta: hospedagem, ônibus, táxi, refeições, souvenirs e passagem aérea."},{"t":"pdf","href":"/guias/fatima-em-3-dias.pdf","note":"Leve o roteiro, as rotas e o orçamento no celular. Grátis, sem cadastro."},{"t":"h","text":"Valores oficiais e fontes","label":"Transparência"},{"t":"p","text":"Conferido em 19/11/2026 nos sites oficiais. Reais pela cotação de venda do Banco Central de 19/11/2026 (euro a R$ 6,4672). Preços e horários mudam: confira antes de ir."},{"t":"ul","items":["**Museu do Santuário:** € 3 (cerca de R$ 20). Segunda a domingo, 9h00 às 12h15 e 14h00 às 17h15 (última entrada).","**Casa de São Francisco e Santa Jacinta Marto:** segunda a domingo, 9h00 às 12h45 e 14h00 às 17h45 (última entrada). Preço não informado. Museu e casa fecham na tarde de 24/12, em 25/12 e em 1/1.","**Mosteiro da Batalha:** € 15 (cerca de R$ 98); € 7,50 (cerca de R$ 49) para 65+ e 13 a 24 anos; até 12 anos grátis. 9h00 às 18h00 de 16/10 a 31/3.","**Mosteiro de Alcobaça:** € 15 (cerca de R$ 98). 9h00 às 17h30 de 1/11 a 31/3.","**Terço na Capelinha:** segunda a sexta, 18h30. **Horário de inverno:** de 1/11 até a Páscoa."]},{"t":"tip","items":["Turismo Centro de Portugal: [Fátima](https://turismodocentro.pt/artigo/fatima-altar-do-mundo/), [roteiro de um dia](https://turismodocentro.pt/artigo/roteiro-de-um-dia-em-fatima/), [Santuário](https://turismodocentro.pt/poi/santuario-nossa-senhora-de-fatima/) e [pratos típicos](https://turismodocentro.pt/artigo/pratos-tipicos-do-centro-de-portugal/)","GNR: [peregrinos de carro](https://www.gnr.pt/fatima_carro.aspx)","Mosteiros: [Batalha](https://mosteirobatalha.gov.pt/visita), [Alcobaça](https://www.museusemonumentos.pt/pt/museus-e-monumentos/mosteiro-de-alcobaca), [bilhetes e descontos](https://www.museusemonumentos.pt/pt/pagina/bilhetes), [bilheteira da Batalha](https://mmp.bymeoblueticket.pt/pt/event/14743/mosteiro-de-santa-maria-da-vitoria-batalha) e [bilheteira de Alcobaça](https://mmp.bymeoblueticket.pt/pt/event/14718/mosteiro-de-alcobaca)","Câmara Municipal de Ourém: [site](https://www.ourem.pt/) e [mês gastronômico](https://www.ourem.pt/setembro-mes-gastronomico-saudades-do-sabor/)","Transporte: [FlixBus Lisboa](https://www.flixbus.com/bus-routes/bus-lisbon-fatima), [FlixBus Porto](https://www.flixbus.com/bus-routes/bus-porto-fatima), [Rede Expressos](https://rede-expressos.pt/pt/) e [CP](https://cp.pt/info/documents/d/cp/comboios-alfa-pendular-intercidades-lisboa-norte-sul-1)","Entrada: [Your Europe](https://europa.eu/youreurope/citizens/travel/entry-exit/non-eu-nationals/index_en.htm), [EUR-Lex](https://eur-lex.europa.eu/legal-content/PT/TXT/HTML/?uri=CELEX:32018R1806), [EES e ETIAS](https://home-affairs.ec.europa.eu/news/main-differences-between-ees-and-etias-what-travellers-need-know-2026-04-28_en) e [ETIAS](https://home-affairs.ec.europa.eu/policies/schengen/smart-borders/european-travel-information-authorisation-system_en)","Câmbio: [Banco Central, 19/11/2026](https://www4.bcb.gov.br/Download/fechamento/20261119.csv)"],"title":"Fontes oficiais, conferidas em 19/11/2026"},{"t":"tip","items":["Condições atuais de estacionamento no Santuário","Horário e preço da Casa da Irmã Lúcia e da Casa-Museu","Horários e preços de ônibus e de trem","Distância de Fátima à Batalha e a Alcobaça","Castelo de Ourém","Vestimenta recomendada nos espaços do Santuário","Regras de entrada em Portugal (visto, EES, ETIAS e meios financeiros)","Preço da Casa de São Francisco e Santa Jacinta Marto","Táxi e transfer, refeições e hospedagem: sem fonte oficial de preço"],"title":"O que este guia não informa"},{"t":"p","text":"Preços, horários e regras mudam: confira nas fontes acima antes de ir. As estimativas de tempo e esforço e as dicas marcadas como da Rota Certa são recomendações nossas, não dados oficiais."},{"t":"p","text":"Foto de capa: Marco F. / Pexels."},{"t":"whatsapp"},{"t":"p","text":"Quer montar o roteiro da viagem inteira? Use o [Planner grátis da Rota Certa](https://rotacertapassagens.com/#/planner)."},{"t":"contato"},{"t":"afiliado"}]', 11);
